// Master Event Classifier
const eventType = $input.first().json.event_type || 'unknown';
const eventData = $input.first().json;

// Determine routing
let route = 'unknown';
let priority = 'normal';
let context = {};

if (eventType === 'file_upload') {
  route = 'document_ingestion';

  // Check for transition context
  if (eventData.transition_id) {
    priority = eventData.transition_type === 'major' ? 'critical' : 'high';
    context.transition = true;
  }

  // Check for offboarding source
  if (eventData.source === 'offboarding') {
    priority = 'high';
    context.offboarding_sourced = true;
  }

} else if (eventType === 'message' || eventType === 'communication') {
  route = 'message_processing';
  priority = 'normal';

  // Check user context
  if (eventData.user_status === 'onboarding') {
    context.onboarding_user = true;
  } else if (eventData.user_status === 'offboarding') {
    context.offboarding_user = true;
  }

} else if (eventType === 'user_created') {
  route = 'user_onboarding';
  priority = 'high';

} else if (eventType === 'user_offboarding') {
  route = 'user_offboarding';
  priority = 'high';

} else if (eventType === 'role_change') {
  route = 'personnel_transition';
  priority = 'high';

} else if (eventType === 'transition_initiated') {
  route = 'transition_management';
  priority = eventData.transition_type === 'major' ? 'critical' : 'high';

} else if (eventType === 'learning_request') {
  route = 'user_requested_learning';
  priority = 'normal';

} else if (eventType === 'search_query') {
  route = 'search_retrieval';
  priority = 'normal';

} else if (eventType === 'batch_processing') {
  route = 'batch_ingestion';
  priority = 'low';
}

return [{
  json: {
    ...eventData,
    routing: {
      route: route,
      priority: priority,
      context: context,
      timestamp: new Date().toISOString()
    }
  }
}];

// Aggregate all sources for baseline generation
const product = $input.item(0).json.product;
const currentDocs = $input.item(1).json.documents || [];
const activeOverrides = $input.item(2).json.overrides || [];
const recentQA = $input.item(3).json.qa_pairs || [];
const temporalUpdates = $input.item(4).json.updates || [];
const offboardingKnowledge = $input.item(5).json.knowledge || [];

return [{
  json: {
    product: product,
    baseline_id: `bp-${product}-${Date.now()}`,
    sources: {
      current_documents: currentDocs.map(d => ({
        doc_id: d.doc_id,
        type: d.document_type,
        version: d.version,
        content_summary: d.summary
      })),
      active_overrides: activeOverrides.map(o => ({
        message_id: o.message_id,
        content: o.content,
        affected_docs: o.override_analysis.documents,
        approved_date: o.approved_date
      })),
      recent_qa: recentQA.map(qa => ({
        question: qa.content,
        answer: qa.answer,
        frequency: qa.frequency || 1
      })),
      temporal_updates: temporalUpdates.map(u => ({
        update_id: u.message_id,
        content: u.content,
        processed_date: u.processed_date
      })),
      offboarding_insights: offboardingKnowledge.map(k => ({
        source_user: k.user_id,
        insights: k.undocumented_knowledge,
        validated: true
      }))
    },
    created_date: new Date().toISOString()
  }
}];

// Parse baseline and check for conflicts
const response = $input.first().json;
const baseline = JSON.parse(response.content[0].text);
const sourceData = $input.item(1).json;

const hasUnresolvedConflicts = baseline.unresolved_conflicts && baseline.unresolved_conflicts.length > 0;
const lowConfidenceSections = baseline.sections.filter(s => s.confidence < 0.7);

return [{
  json: {
    baseline_id: sourceData.baseline_id,
    product: sourceData.product,
    baseline_content: baseline,
    requires_review: hasUnresolvedConflicts || lowConfidenceSections.length > 0,
    review_items: {
      unresolved_conflicts: baseline.unresolved_conflicts || [],
      low_confidence_sections: lowConfidenceSections.map(s => s.section_id)
    },
    sources: sourceData.sources,
    created_date: sourceData.created_date
  }
}];

