// Generate comprehensive baseline report
const baseline = $input.first().json;

const report = {
  baseline_id: baseline.baseline_id,
  product: baseline.product,
  status: 'published',
  created_date: baseline.created_date,
  approved_date: baseline.approved_date || new Date().toISOString(),
  sources_used: {
    documents: baseline.sources.current_documents.length,
    overrides: baseline.sources.active_overrides.length,
    qa_pairs: baseline.sources.recent_qa.length,
    temporal_updates: baseline.sources.temporal_updates.length,
    offboarding_insights: baseline.sources.offboarding_insights.length
  },
  quality_metrics: {
    average_confidence: baseline.baseline_content.sections.reduce((sum, s) => sum + s.confidence, 0) / baseline.baseline_content.sections.length,
    sections_count: baseline.baseline_content.sections.length,
    conflicts_resolved: baseline.review_items?.unresolved_conflicts?.length || 0,
    low_confidence_sections: baseline.review_items?.low_confidence_sections?.length || 0
  },
  impact: {
    learning_modules_updated: baseline.modules_updated || 0,
    active_learners_notified: baseline.learners_notified || 0,
    search_index_updated: true
  },
  next_update_scheduled: new Date(Date.now() + 7*24*60*60*1000).toISOString()
};

return [{
  json: {
    status: 'success',
    report: report,
    message: `Baseline for ${baseline.product} successfully generated and published`
  }
}];

// Log rejection and notify
const baseline = $input.first().json;

return [{
  json: {
    status: 'rejected',
    baseline_id: baseline.baseline_id,
    product: baseline.product,
    rejection_reason: baseline.rejection_reason,
    rejected_by: baseline.reviewer,
    rejected_date: new Date().toISOString(),
    message: 'Baseline rejected - requires revision'
  }
}];

// Extract file metadata and calculate hash
const crypto = require('crypto');
const fileData = $input.first().json;

// Read file content
const fileContent = await window.fs.readFile(fileData.file_path);
const fileHash = crypto.createHash('sha256').update(fileContent).digest('hex');

return [{
  json: {
    file_id: `file-${Date.now()}`,
    file_path: fileData.file_path,
    file_name: fileData.file_name,
    file_size: fileContent.length,
    file_hash: fileHash,
    modified_date: fileData.modified_date || new Date().toISOString(),
    content: fileContent.toString('utf8'),
    ingestion_date: new Date().toISOString(),
    priority: fileData.priority || 'normal',
    transition_context: fileData.transition_id || null,
    source: fileData.source || 'standard'
  }
}];

// Parse Claude response and check confidence
const response = $input.first().json;
const claudeContent = JSON.parse(response.content[0].text);

const item = $input.first().json;

return [{
  json: {
    ...item,
    classification: {
      class: claudeContent.class,
      type: claudeContent.type,
      confidence: claudeContent.confidence,
      rationale: claudeContent.rationale
    },
    requires_review: claudeContent.confidence < 0.7
  }
}];

// Parse version info and merge with document data
const response = $input.first().json;
const versionInfo = JSON.parse(response.content[0].text);

const previousData = $input.item(1).json; // Get data from previous node

return [{
  json: {
    ...previousData,
    version_info: versionInfo,
    version: versionInfo.version || null,
    publish_date: versionInfo.publish_date || previousData.modified_date,
    author: versionInfo.author || 'unknown'
  }
}];

// Determine currency status
const currentDoc = $input.first().json;
const existingDocs = $input.item(1).json.documents || [];

let status = 'current';
let superseded_by = null;
let supersedes = null;

if (existingDocs.length > 0) {
  const latest = existingDocs[0];

  // Compare versions if both have version numbers
  if (currentDoc.version && latest.version) {
    const currentVer = parseFloat(currentDoc.version.replace(/[^0-9.]/g, ''));
    const latestVer = parseFloat(latest.version.replace(/[^0-9.]/g, ''));

    if (currentVer < latestVer) {
      status = 'superseded';
      superseded_by = latest.doc_id;
    } else if (currentVer > latestVer) {
      status = 'current';
      supersedes = latest.doc_id;
      // Mark old doc as superseded
    }
  } else {
    // Compare by date
    const currentDate = new Date(currentDoc.publish_date);
    const latestDate = new Date(latest.publish_date);

    if (currentDate < latestDate) {
      status = 'superseded';
      superseded_by = latest.doc_id;
    } else {
      status = 'current';
      supersedes = latest.doc_id;
    }
  }
}

// Check for messaging overrides
const overrideCheck = await $input.first().getNode('check-overrides').execute();

if (overrideCheck && overrideCheck.length > 0) {
  status = 'overridden';
  currentDoc.overridden_by = overrideCheck.map(o => o.message_id);
}

return [{
  json: {
    ...currentDoc,
    currency_status: status,
    superseded_by: superseded_by,
    supersedes: supersedes
  }
}];

// Apply Claude's chunking recommendations
const response = $input.first().json;
const chunkingSchema = JSON.parse(response.content[0].text);
const docData = $input.item(1).json;

const chunks = [];

for (let i = 0; i < chunkingSchema.chunks.length; i++) {
  const schema = chunkingSchema.chunks[i];

  const chunkContent = docData.content.substring(
    schema.start_char,
    schema.end_char
  );

  chunks.push({
    chunk_id: `${docData.file_id}-chunk-${i + 1}`,
    document_id: docData.file_id,
    chunk_index: i + 1,
    chunk_type: schema.chunk_type,
    content: chunkContent,
    standalone_score: schema.standalone_score,
    requires_context_from: schema.context_dependencies.map(
      dep => typeof dep === 'number' ? `${docData.file_id}-chunk-${dep}` : dep
    ),
    provides_context_to: i < chunkingSchema.chunks.length - 1 
      ? [`${docData.file_id}-chunk-${i + 2}`] 
      : [],
    char_range: [schema.start_char, schema.end_char],
    semantic_summary: schema.summary || '',
    created_date: new Date().toISOString()
  });
}

return chunks.map(chunk => ({ json: chunk }));

// Merge facts with chunk data
const response = $input.first().json;
const facts = JSON.parse(response.content[0].text);
const chunkData = $input.item(1).json;

return [{
  json: {
    ...chunkData,
    extracted_facts: facts.facts || [],
    entities: facts.entities || [],
    temporal_markers: facts.temporal_markers || []
  }
}];

// Create graph relationships
const doc = $input.first().json;
const relationships = [];

// Version relationships
if (doc.supersedes) {
  relationships.push({
    type: 'SUPERSEDES',
    from: doc.file_id,
    to: doc.supersedes,
    created: new Date().toISOString()
  });
}

if (doc.superseded_by) {
  relationships.push({
    type: 'SUPERSEDED_BY',
    from: doc.file_id,
    to: doc.superseded_by,
    created: new Date().toISOString()
  });
}

// Chunk context relationships
if (doc.chunks) {
  doc.chunks.forEach(chunk => {
    if (chunk.requires_context_from) {
      chunk.requires_context_from.forEach(dep => {
        relationships.push({
          type: 'REQUIRES_CONTEXT',
          from: chunk.chunk_id,
          to: dep,
          created: new Date().toISOString()
        });
      });
    }
  });
}

return relationships.map(rel => ({ json: rel }));

// Final response
const doc = $input.first().json;

return [{
  json: {
    status: 'success',
    document_id: doc.file_id,
    chunks_created: doc.chunks ? doc.chunks.length : 0,
    currency_status: doc.currency_status,
    classification: doc.classification,
    message: 'Document successfully ingested and indexed'
  }
}];

// Parse Claude classification
const response = $input.first().json;
const classification = JSON.parse(response.content[0].text);
const messageData = $input.item(1).json;

return [{
  json: {
    message_id: `msg-${Date.now()}`,
    ...messageData,
    classification: classification,
    requires_review: classification.confidence < 0.7
  }
}];

// Process Question
const msg = $input.first().json;

return [{
  json: {
    ...msg,
    tags: {
      primary: ['question', 'query'],
      status: ['awaiting_human_answer'],
      urgency: [msg.classification.urgency],
      entities: msg.classification.related_entities
    },
    answer_status: 'unanswered',
    queued_for_answer: new Date().toISOString()
  }
}];

