// Process update message (Class 3)
const msg = $input.first().json;

return [{
  json: {
    ...msg,
    tags: {
      primary: ['update', 'temporal'],
      status: ['active'],
      urgency: [msg.classification.urgency],
      entities: msg.classification.related_entities
    },
    processed_date: new Date().toISOString()
  }
}];

// Generate final response
const msg = $input.first().json;

let responseMsg = '';
if (msg.classification.message_type === 'question') {
  responseMsg = 'Question queued for team response';
} else if (msg.classification.message_type === 'directive') {
  responseMsg = msg.override_analysis ? 'Directive queued for approval' : 'Directive processed';
} else if (msg.classification.message_type === 'update') {
  responseMsg = 'Update processed and baseline triggered';
}

return [{
  json: {
    status: 'success',
    message_id: msg.message_id,
    message_type: msg.classification.message_type,
    system_changing: msg.classification.system_changing || false,
    requires_approval: msg.override_analysis ? true : false,
    message: responseMsg
  }
}];

// Parse classification and load config
const response = $input.first().json;
const classification = JSON.parse(response.content[0].text);
const eventData = $input.item(1).json;

return [{
  json: {
    transition_id: `trans-${Date.now()}`,
    ...eventData,
    classification: classification,
    transition_type: classification.transition_type,
    severity: classification.severity,
    initiated_date: new Date().toISOString()
  }
}];

// Prepare parallel workflows based on config
const transData = $input.first().json;
const config = $input.item(1).json;

const workflows = [];

// Determine which workflows to trigger
if (config.offboarding_requirements.survey_depth !== 'none') {
  workflows.push({
    workflow_name: 'offboarding',
    workflow_id: 'user_offboarding_workflow_id',
    params: {
      user_ids: transData.affected_users,
      survey_type: config.offboarding_requirements.survey_depth
    }
  });
}

if (config.onboarding_requirements.roadmap_update === 'required') {
  workflows.push({
    workflow_name: 'roadmap_update',
    workflow_id: 'roadmap_update_workflow_id',
    params: {
      products: transData.affected_products
    }
  });
}

workflows.push({
  workflow_name: 'documentation_review',
  workflow_id: 'doc_review_workflow_id',
  params: {
    document_ids: transData.affected_documents,
    priority: config.offboarding_requirements.documentation_priority
  }
});

workflows.push({
  workflow_name: 'communication',
  workflow_id: 'communication_workflow_id',
  params: {
    stakeholders: transData.stakeholders,
    urgency: transData.severity
  }
});

return workflows.map(w => ({ json: { ...transData, config: config, workflow: w } }));

// Flag all documents for review
const docs = $input.first().json.documents || [];
const transData = $input.item(1).json;

const reviewTasks = docs.map(doc => ({
  task_id: `review-${Date.now()}-${doc._id}`,
  document_id: doc._id,
  transition_id: transData.transition_id,
  priority: transData.config.offboarding_requirements.documentation_priority,
  status: 'pending',
  created_date: new Date().toISOString()
}));

return reviewTasks.map(task => ({ json: task }));

// Generate communication messages
const transData = $input.first().json;

let message = '';
let urgencyEmoji = '';

if (transData.severity === 'critical') {
  urgencyEmoji = '🚨';
  message = `CRITICAL TRANSITION: ${transData.event_description}`;
} else if (transData.severity === 'high') {
  urgencyEmoji = '⚠️';
  message = `Important Transition: ${transData.event_description}`;
} else {
  urgencyEmoji = 'ℹ️';
  message = `Transition Notice: ${transData.event_description}`;
}

return [{
  json: {
    ...transData,
    notification_message: `${urgencyEmoji} *${transData.transition_type.toUpperCase()} TRANSITION*\n\n${message}\n\n*Affected Systems:* ${transData.affected_products.join(', ')}\n*Affected Users:* ${transData.affected_users.length}\n*Timeline:* ${transData.config.offboarding_requirements.transition_time_days} days\n\nActions required: Check your task queue for specific items.`
  }
}];

// Aggregate results from all workflows
const results = $input.all();

const summary = {
  offboarding_initiated: results.some(r => r.json.workflow_name === 'offboarding'),
  documentation_flagged: results.filter(r => r.json.workflow_name === 'documentation_review').length,
  notifications_sent: results.some(r => r.json.workflow_name === 'communication'),
  roadmap_updated: results.some(r => r.json.workflow_name === 'roadmap_update')
};

const transData = results[0].json;

return [{
  json: {
    transition_id: transData.transition_id,
    status: 'workflows_initiated',
    summary: summary,
    next_steps: [
      'Monitor offboarding survey completion',
      'Track document review progress',
      'Update baseline when ready'
    ]
  }
}];

// Monitor transition completion
const trans = $input.first().json;

return [{
  json: {
    status: 'success',
    transition_id: trans.transition_id,
    message: `${trans.transition_type} transition initiated successfully`,
    workflows_started: Object.keys(trans.summary).filter(k => trans.summary[k]).length,
    monitoring_url: `${trans.portal_url}/transitions/${trans.transition_id}`
  }
}];

// Prepare survey for user
const response = $input.first().json;
const survey = JSON.parse(response.content[0].text);
const userData = $input.item(1).json;

return [{
  json: {
    survey_id: `offboard-${userData.user_id}-${Date.now()}`,
    user_id: userData.user_id,
    generated_date: new Date().toISOString(),
    survey: survey,
    status: 'pending',
    deadline: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString()
  }
}];

// Parse analysis and determine next steps
const response = $input.first().json;
const analysis = JSON.parse(response.content[0].text);
const surveyData = $input.item(1).json;

return [{
  json: {
    survey_id: surveyData.survey_id,
    user_id: surveyData.user_id,
    analysis: analysis,
    needs_clarification: analysis.items_needing_clarification.length > 0,
    has_contradictions: analysis.contradictions.length > 0,
    undocumented_knowledge: analysis.undocumented_procedures,
    action_items: analysis.action_items
  }
}];

// Extract and validate undocumented procedures
const data = $input.first().json;

const validationTasks = data.undocumented_knowledge.map(item => ({
  validation_id: `val-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
  source: 'offboarding_survey',
  user_id: data.user_id,
  claim: item.description,
  documented: false,
  contradiction: null,
  priority: item.criticality || 'medium',
  status: 'pending_review',
  created_date: new Date().toISOString()
}));

return validationTasks.map(task => ({ json: task }));

