// Analyze assessment responses and generate personalized path
const responses = $input.first().json.responses;
const userData = $input.item(1).json;
const roadmap = $input.item(2).json;

// Get role-based path from roadmap
const roleModules = roadmap.role_based_paths[userData.role] || [];

// Filter/adjust based on assessment
let personalizedModules = roleModules.map(moduleId => {
  const module = roadmap.learning_modules.find(m => m.module_id === moduleId);

  return {
    module_id: module.module_id,
    module_name: module.module_name,
    status: 'not_started',
    due_date: new Date(Date.now() + module.estimated_time_hours * 24 * 60 * 60 * 1000).toISOString(),
    priority: module.required ? 'high' : 'medium'
  };
});

return [{
  json: {
    user_id: userData.user_id,
    assigned_roadmap: roadmap.roadmap_id,
    personalized_path: personalizedModules,
    assessment_results: responses,
    start_date: new Date().toISOString(),
    estimated_completion: new Date(Date.now() + 60 * 24 * 60 * 60 * 1000).toISOString()
  }
}];

// Check prerequisites
const recommendation = JSON.parse($input.first().json.content[0].text);
const user = $input.item(1).json;

const completedModules = user.onboarding.personalized_path
  .filter(m => m.status === 'completed')
  .map(m => m.module_id);

const missingPrereqs = recommendation.prerequisites
  .filter(p => !completedModules.includes(p));

return [{
  json: {
    ...recommendation,
    user_id: user.user_id,
    missing_prerequisites: missingPrereqs,
    can_proceed: missingPrereqs.length === 0
  }
}];

// Update progress and calculate metrics
const completion = $input.first().json;
const user = $input.item(1).json;

// Update module status
const updatedPath = user.onboarding.personalized_path.map(m => {
  if (m.module_id === completion.module_id) {
    return {
      ...m,
      status: 'completed',
      completed_date: new Date().toISOString(),
      score: completion.score,
      passed: completion.score >= completion.passing_score
    };
  }
  return m;
});

// Calculate overall progress
const totalModules = updatedPath.length;
const completedModules = updatedPath.filter(m => m.status === 'completed').length;
const progressPercentage = (completedModules / totalModules) * 100;

// Calculate mastery by area
const masteryByArea = {};
// ... (mastery calculation logic)

return [{
  json: {
    user_id: user.user_id,
    updated_path: updatedPath,
    overall_progress: {
      modules_completed: completedModules,
      modules_total: totalModules,
      completion_percentage: progressPercentage
    },
    mastery_by_area: masteryByArea
  }
}];
